#!/usr/bin/env bash
# Print a .env for local development from Secret Manager (LLD-2, LLD-18). Usage: bash infra/gcp/env.sh dev > .env
# The output contains secrets — .env is git-ignored. Locally Postgres is reached through the Cloud SQL Auth Proxy.
set -euo pipefail

ENV="${1:-dev}"
PROJECT="${GCP_PROJECT:-$(gcloud config get-value project 2>/dev/null)}"
REGION="${GCP_REGION:-asia-south1}"
P="mcs-${ENV}"
s() { gcloud --project "$PROJECT" secrets versions access latest --secret "$P-$1" 2>/dev/null || true; }

DB_PW="$(s db-password)"
DB_RO_PW="$(s db-ro-password)"
cat <<EOF
# Generated by infra/gcp/env.sh $ENV — do not commit.
ENV=$ENV
GCP_PROJECT=$PROJECT
GCP_REGION=$REGION
CLOUDSQL_INSTANCE=$PROJECT:$REGION:mcs-$ENV
DATABASE_URL=postgresql+psycopg://mcs:$DB_PW@127.0.0.1:5432/mcs
DATABASE_URL_RO=postgresql+psycopg://mcs_ro:$DB_RO_PW@127.0.0.1:5432/mcs
DATABASE_URL_TEST=postgresql+psycopg://mcs:$DB_PW@127.0.0.1:5432/mcs_test
NEO4J_URI=$(s neo4j-uri)
NEO4J_USER=$(s neo4j-user)
NEO4J_PASSWORD=$(s neo4j-password)
NEO4J_DATABASE=$(s neo4j-database)
NEO4J_RO_USER=
NEO4J_RO_PASSWORD=
PROVIDER=vertex
GCS_BUCKET=mcs-$ENV-uploads
MAIL_ADAPTER=demo
SUPPORT_ADDRESS=support@matsui-demo.example
RETENTION_DAYS=30
NEXTAUTH_SECRET=$(s nextauth-secret)
AGENT_API_URL=http://localhost:8000
EOF
